head.script:
//
(function() {
  var url = window.location.href;
  if (url.indexOf('?m=1') !== -1) {
    window.location.replace(url.replace('?m=1', '?m=0'));
  } else if (url.indexOf('?m=0') === -1 && window.location.search === '' && /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
    var separator = url.indexOf('?') !== -1 ? '&' : '?';
    window.location.replace(url + separator + 'm=0');
  }
})();
//

head.b:skin:
/* Reset and Core Styles */
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background-color: #090c10;
  color: #f0f3f8;
  font-family: 'Hind Siliguri', 'Outfit', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  scroll-behavior: smooth;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: #090c10;
}
::-webkit-scrollbar-thumb {
  background: #1e293b;
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: #10b981;
}

/* Premium Glassmorphic Inputs & Panels */
.glass-panel {
  background: rgba(15, 22, 36, 0.7);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.06);
}
.glass-input {
  background: rgba(8, 12, 21, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #ffffff;
  transition: all 0.2s ease;
}
.glass-input:focus {
  border-color: #10b981;
  background: rgba(8, 12, 21, 0.8);
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.2);
  outline: none;
}

/* Grid system & custom helpers */
.animate-pulse-slow {
  animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: .5; }
}

/* News Ticker Animation */
@keyframes marquee {
  0% {
    transform: translate3d(0, 0, 0);
  }
  100% {
    transform: translate3d(-100%, 0, 0);
  }
}
.animate-marquee {
  display: inline-block;
  padding-left: 100%;
  animation: marquee 35s linear infinite;
}
.animate-marquee:hover {
  animation-play-state: paused;
}

/* Font modifiers */
.font-bangla {
  font-family: 'Hind Siliguri', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
}

/* Layout-safe ad containers */
.ad-container {
  overflow: hidden;
  max-width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 1rem 0;
}

