body.script:
//

// Global Error Handling overlay removed to prevent cross-origin script error boxes

// 1. Supabase Credentials
const supabaseUrl = 'https://wkikuysbirrcmbextkvp.supabase.co';
const supabaseAnonKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6IndraWt1eXNiaXJyY21iZXh0a3ZwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODExODIzNDEsImV4cCI6MjA5Njc1ODM0MX0.eNrSGZFdjNEoy1OE1w9Zj3OwyIw1lZCRdOHIRiP-IBA';
let supabaseDb = null;

// 2. Base Endpoint URL for Dashboard Actions
const BACKEND_BASE = 'https://kheledao.kheledao.workers.dev';

// 3. Application State Object
const state = {
  activeTab: 'live',            // 'streaming' | 'live' | 'upcoming' | 'finished' | 'channels'
  matches: [],
  espnScores: [],
  channels: [],
  announcements: [],
  systemConfig: null,
  tickerSettings: null,
  adsterra: null,
  dismissedAnnouncements: {},

  // View counts & Active viewers metrics
  totalViews: 0,
  liveCount: 0,
  isNoticeModalOpen: false,

  // Watch mode state
  watchMatchId: null,
  streamingMatch: null,
  activeStreamIndex: 0,
  playerError: null,
  reconnecting: false,
  bufferState: 'Healthy',
  activeSideTab: 'commentary',  // 'commentary' | 'events' | 'telemetry' | 'lineup'
  commentaryData: null,
  loadingCommentary: false,
  playerKey: 0,

  // TV Channel mode state
  watchChannelId: null,
  selectedChannelUrl: null,
  selectedChannelName: '',

  // Search filters
  upcomingQuery: '',
  finishedQuery: '',
  channelsQuery: '',

  // Initialization flags
  hasInitializedTab: false,
  loading: true,

  // Page render tracking to prevent player reload "jhilik"
  lastRenderedPage: null
};

// 4. Timer handles
let globalInterval = null;
let commentaryInterval = null;
let detectorInterval = null;
let blackFrameCount = 0;
let hlsRef = { current: null };

// 5. Utility alias maps
const teamNameAliases = {
  'united states': ['usa', 'us', 'united states of america', 'u.s.a.'],
  'south korea': ['korea republic', 'korea', 'korea rep.', 'republic of korea'],
  'ivory coast': ["cote d'ivoire", 'côte d\'ivoire', 'cote divoire'],
  'dr congo': ['democratic republic of congo', 'congo dr', 'dem. rep. congo', 'congo'],
  'cabo verde': ['cape verde'],
  'czech republic': ['czechia'],
  'bosnia': ['bosnia and herzegovina', 'bosnia &amp; herzegovina', 'bosnia-herzegovina'],
  'curacao': ['curaçao'],
  'turkey': ['türkiye', 'turkiye']
};

function normalizeTeamName(name) {
  if (!name) return '';
  const lower = name.trim().toLowerCase();
  for (const [canonical, aliases] of Object.entries(teamNameAliases)) {
    if (lower === canonical || aliases.includes(lower)) {
      return canonical;
    }
  }
  return lower;
}

function teamsMatch(dbName, espnName) {
  const norm1 = normalizeTeamName(dbName);
  const norm2 = normalizeTeamName(espnName);
  if (norm1 === norm2) return true;
  if (norm1.includes(norm2) || norm2.includes(norm1)) return true;
  return false;
}

function matchChannelWithTeams(channelName, homeTeam, awayTeam) {
  if (!channelName || !homeTeam || !awayTeam) return false;
  const nameLower = channelName.toLowerCase();
  const homeLower = homeTeam.toLowerCase();
  const awayLower = awayTeam.toLowerCase();

  if (nameLower.includes(homeLower) && nameLower.includes(awayLower)) return true;

  const normHome = normalizeTeamName(homeTeam);
  const normAway = normalizeTeamName(awayTeam);
  if (normHome && normAway && nameLower.includes(normHome) && nameLower.includes(normAway)) return true;

  const homeShort = homeLower.substring(0, 3);
  const awayShort = awayLower.substring(0, 3);
  if (homeShort.length >= 3 && awayShort.length >= 3 && nameLower.includes(homeShort) && nameLower.includes(awayShort)) return true;

  const homeWords = homeLower.split(/[\s-]+/).filter(w => w.length > 2);
  const awayWords = awayLower.split(/[\s-]+/).filter(w => w.length > 2);
  if (homeWords.length > 0 && awayWords.length > 0) {
    const hasHomeWord = homeWords.some(w => nameLower.includes(w));
    const hasAwayWord = awayWords.some(w => nameLower.includes(w));
    if (hasHomeWord && hasAwayWord) return true;
  }
  return false;
}

function getYouTubeEmbedUrl(url) {
  if (!url) return '';
  let videoId = '';
  try {
    if (url.includes('youtube.com/embed/')) return url;
    if (url.includes('youtu.be/')) {
      videoId = url.split('youtu.be/')[1]?.split(/[?#]/)[0] || '';
    } else if (url.includes('youtube.com/watch')) {
      const urlParams = new URLSearchParams(url.split('?')[1] || '');
      videoId = urlParams.get('v') || '';
    } else if (url.includes('youtube.com/v/')) {
      videoId = url.split('/v/')[1]?.split(/[?#]/)[0] || '';
    }
  } catch (e) {
    console.error(e);
  }
  return videoId ? `https://www.youtube.com/embed/${videoId}?autoplay=1&mute=0` : url;
}

// 6. Router logic mapping
function routeHash() {
  // Clear last rendered tracking to force full skeleton build on route change
  state.lastRenderedPage = null;
  const params = new URLSearchParams(window.location.search);
  const watch = params.get('watch');
  const channel = params.get('channel');

  if (watch) {
    state.watchMatchId = watch;
    state.watchChannelId = null;
  } else if (channel) {
    state.watchChannelId = channel;
    state.watchMatchId = null;
  } else {
    state.watchMatchId = null;
    state.watchChannelId = null;
  }

  state.playerError = null;
  state.reconnecting = false;
  state.bufferState = 'Healthy';
  state.activeStreamIndex = 0;

  render();
  if (state.watchMatchId) {
    loadWatchMatchDetails();
  } else if (state.watchChannelId) {
    loadWatchChannelDetails();
  }
}

function navigate(paramsMap) {
  const url = new URL(window.location.href);
  for (const [key, val] of Object.entries(paramsMap)) {
    if (val === null) {
      url.searchParams.delete(key);
    } else {
      url.searchParams.set(key, val);
    }
  }
  window.history.pushState({}, '', url.toString());
  routeHash();
}

window.addEventListener('popstate', routeHash);

// 7. Initial loading and polling
async function initApp() {
  try {
    // Wait for window.supabase (up to 10 seconds)
    let retries = 0;
    while (!window.supabase && retries < 100) {
      await new Promise(r => setTimeout(r, 100));
      retries++;
    }

    if (!window.supabase) {
      throw new Error("Supabase script failed to load from CDN. Please check your internet connection.");
    }

    // Initialize supabaseDb instance safely
    supabaseDb = window.supabase.createClient(supabaseUrl, supabaseAnonKey);

    // Prioritize matches, system config, ticker, and channels first for instant load/player start
    await Promise.all([
      fetchSystemConfig(),
      fetchTickerSettings(),
      fetchMatches(),
      fetchChannels(),
      fetchEspnScores()
    ]);

    // Tab landing default
    if (state.systemConfig && !state.hasInitializedTab) {
      const showStreaming = state.systemConfig.custom_scripts?.enable_streaming_now !== false;
      state.activeTab = showStreaming ? 'streaming' : 'live';
      state.hasInitializedTab = true;
    }

    state.loading = false;
    routeHash();

    // Load secondary/non-critical configurations in the background without blocking
    Promise.all([
      fetchAdsterraConfig(),
      fetchAnnouncements(),
      fetchCounters()
    ]).then(() => {
      render();
    }).catch(e => console.warn("Background configurations load failed:", e));

    // Polling loop every 6 seconds
    if (globalInterval) clearInterval(globalInterval);
    globalInterval = setInterval(async () => {
      await Promise.all([
        fetchMatches(),
        fetchEspnScores(),
        fetchChannels(),
        fetchCounters()
      ]);
      checkKickoffAutoSwitch();
      render();
    }, 6000);

    // Global countdown timer loop
    initMatchCountdowns();

  } catch (err) {
    console.error('Fatal initialization error:', err);
  }
}

async function fetchSystemConfig() {
  const { data, error } = await supabaseDb
    .from('ad_networks')
    .select('*')
    .eq('network_name', 'SystemConfig')
    .maybeSingle();
  if (!error && data) {
    state.systemConfig = data;
  }
}

async function fetchTickerSettings() {
  const { data, error } = await supabaseDb
    .from('ticker_settings')
    .select('*')
    .order('updated_at', { ascending: false })
    .limit(1);
  if (!error && data && data.length > 0) {
    state.tickerSettings = data[0];
  }
}

async function fetchAdsterraConfig() {
  const { data, error } = await supabaseDb
    .from('ad_networks')
    .select('*')
    .eq('network_name', 'Adsterra')
    .maybeSingle();
  if (!error && data) {
    state.adsterra = data;
  }
}

async function fetchMatches() {
  // Use exact database constraints matches_home_team_id_fkey and matches_away_team_id_fkey
  const { data, error } = await supabaseDb
    .from('matches')
    .select(`
      *,
      home_team:teams!matches_home_team_id_fkey(*),
      away_team:teams!matches_away_team_id_fkey(*)
    `)
    .order('match_timestamp', { ascending: true });
  if (!error && data) {
    state.matches = data;
  }
}

async function fetchAnnouncements() {
  const { data, error } = await supabaseDb
    .from('announcements')
    .select('*')
    .eq('status', 'published')
    .order('created_at', { ascending: false });
  if (!error && data) {
    state.announcements = data;
  }
}

async function fetchChannels() {
  const { data, error } = await supabaseDb
    .from('channels')
    .select('*')
    .eq('is_enabled', true)
    .order('created_at', { ascending: false });
  if (!error && data) {
    state.channels = data;
  }
}

async function fetchEspnScores() {
  try {
    const res = await fetch(`${BACKEND_BASE}/api/live-scores`);
    if (res.ok) {
      const data = await res.json();
      state.espnScores = data.scores || [];
    }
  } catch (e) {
    console.warn('Failed to query scoreboard:', e);
  }
}

async function fetchCounters() {
  try {
    const offsetViews = state.tickerSettings?.views_offset !== undefined ? Number(state.tickerSettings.views_offset) : 0;
    const offsetLive = state.tickerSettings?.viewers_offset !== undefined ? Number(state.tickerSettings.viewers_offset) : 0;

    const [viewsRes, liveRes] = await Promise.all([
      supabaseDb.rpc('get_total_views_count'),
      supabaseDb.rpc('get_active_viewers_count')
    ]);

    state.totalViews = (viewsRes.data || 0) + offsetViews;
    state.liveCount = (liveRes.data || 0) + offsetLive;
  } catch (e) {
    console.warn('RPC metrics count load failed:', e);
  }
}

async function logAnalyticsWatch() {
  if (!state.watchMatchId || !state.streamingMatch) return;
  try {
    let sid = sessionStorage.getItem('user_session_id');
    if (!sid) {
      sid = 'sess_' + Math.random().toString(36).substring(2, 15) + Date.now().toString(36);
      sessionStorage.setItem('user_session_id', sid);
    }
    await supabaseDb.from('analytics').insert([{
      event_name: 'web_watch_stream',
      session_id: sid,
      metadata: { match_id: state.streamingMatch.id, tournament: state.streamingMatch.tournament_name }
    }]);
  } catch (e) {
    console.warn('Analytics logging failed:', e);
  }
}

function checkKickoffAutoSwitch() {
  if (!state.systemConfig) return;
  const autoSwitchEnabled = state.systemConfig.custom_scripts?.enable_live_tab_auto_switch !== false;
  if (!autoSwitchEnabled) return;

  const liveOffsetMins = 10;
  const hasMatchClose = state.matches.some(m => {
    if (m.status !== 'upcoming') return false;
    const kickoff = new Date(m.match_timestamp).getTime();
    const diff = kickoff - Date.now();
    return diff > 0 && diff <= liveOffsetMins * 60 * 1000;
  });

  if (hasMatchClose && state.activeTab !== 'live' && !state.watchMatchId && !state.watchChannelId) {
    console.log('[Blogger Auto Switch] Match kickoff close. Switching to Live Now.');
    state.activeTab = 'live';
  }
}

// 8. Match categorization filters
function getCategorizedMatches() {
  const autoFinishEnabled = state.systemConfig?.custom_scripts?.auto_finish_enabled !== false;
  const forceAllLive = state.systemConfig?.custom_scripts?.force_all_live === true;
  const liveOffsetMins = state.systemConfig?.custom_scripts?.match_live_before_minutes !== undefined 
    ? Number(state.systemConfig.custom_scripts.match_live_before_minutes) 
    : 10;
  const durationHours = state.systemConfig?.custom_scripts?.match_duration_hours !== undefined 
    ? Number(state.systemConfig.custom_scripts.match_duration_hours) 
    : 1;
  const durationMins = state.systemConfig?.custom_scripts?.match_duration_minutes !== undefined 
    ? Number(state.systemConfig.custom_scripts.match_duration_minutes) 
    : 45;
  const matchDuration = (durationHours * 60 + durationMins) * 60 * 1000;

  const live = [];
  const upcoming = [];
  const finished = [];

  state.matches.forEach(m => {
    const kickoff = new Date(m.match_timestamp).getTime();

    // Force all live check
    if (forceAllLive && m.status === 'upcoming') {
      live.push(m);
      return;
    }

    // Check Live status
    const isLive = m.status === 'live' || (
      m.status !== 'finished' && m.status !== 'cancelled' && m.status !== 'postponed' &&
      Date.now() >= (kickoff - liveOffsetMins * 60 * 1000) &&
      Date.now() < (kickoff + matchDuration)
    );

    // Check Upcoming status
    const isUpcoming = m.status === 'upcoming' && Date.now() < (kickoff - liveOffsetMins * 60 * 1000);

    // Check Finished status
    const isFinished = m.status === 'finished' || m.status === 'cancelled' || m.status === 'postponed' || (
      autoFinishEnabled && m.status !== 'finished' && m.status !== 'cancelled' && m.status !== 'postponed' &&
      Date.now() >= (kickoff + matchDuration)
    );

    if (isLive) live.push(m);
    else if (isUpcoming) upcoming.push(m);
    else if (isFinished) finished.push(m);
  });

  // Filter by search terms
  const filter = (list, query) => {
    if (!query) return list;
    const q = query.toLowerCase().trim();
    return list.filter(m => {
      const home = (m.home_team?.name || m.home_team_custom_name || '').toLowerCase();
      const away = (m.away_team?.name || m.away_team_custom_name || '').toLowerCase();
      const tournament = (m.tournament_name || '').toLowerCase();
      return home.includes(q) || away.includes(q) || tournament.includes(q);
    });
  };

  return {
    live,
    upcoming: filter(upcoming, state.upcomingQuery),
    finished: filter(finished, state.finishedQuery).sort((a,b) => new Date(b.match_timestamp) - new Date(a.match_timestamp))
  };
}

// 9. Load details for Watch page
async function loadWatchMatchDetails() {
  // Find matching item
  let matchId = state.watchMatchId;
  if (!matchId) {
    const cats = getCategorizedMatches();
    const streamingFeatured = cats.live.length > 0 ? cats.live[0] : (cats.upcoming.length > 0 ? cats.upcoming[0] : (cats.finished.length > 0 ? cats.finished[0] : null));
    if (streamingFeatured) {
      matchId = streamingFeatured.id;
    }
  }
  if (!matchId) return;

  const match = state.matches.find(m => String(m.id) === String(matchId));
  if (!match) return;
  state.streamingMatch = match;

  // Load streams
  const { data: streams, error } = await supabaseDb
    .from('streams')
    .select('*')
    .eq('match_id', match.id)
    .eq('is_enabled', true);

  let streamItems = [];
  if (!error && streams && streams.length > 0) {
    const stream = streams[0];
    streamItems = Array.isArray(stream.urls) && stream.urls.length > 0
      ? stream.urls
      : [
          { label: 'Primary Server', url: stream.primary_url },
          { label: 'Backup Feed 1', url: stream.backup_url_1 },
          { label: 'Backup Feed 2', url: stream.backup_url_2 },
          { label: 'Backup Feed 3', url: stream.backup_url_3 }
        ].filter(item => !!item.url);
  }

  // Add YouTube stream if globally active
  if (state.systemConfig?.custom_scripts?.youtube_live_enabled && state.systemConfig?.custom_scripts?.youtube_live_url) {
    streamItems.push({
      label: state.systemConfig.custom_scripts.youtube_live_label || 'robeeee',
      url: state.systemConfig.custom_scripts.youtube_live_url
    });
  }

  state.streamingUrls = streamItems.map(s => s.url);
  state.streamingLabels = streamItems.map(s => s.label || 'Server');

  // Fetch scoreboard for this specific match date to verify tiebreaker/shootout/live score updates
  if (match.match_timestamp) {
    try {
      const d = new Date(match.match_timestamp);
      const yr = d.getFullYear();
      const mo = String(d.getMonth() + 1).padStart(2, '0');
      const dy = String(d.getDate()).padStart(2, '0');
      const dateStr = `${yr}${mo}${dy}`;

      const scoreRes = await fetch(`${BACKEND_BASE}/api/live-scores?date=${dateStr}`);
      if (scoreRes.ok) {
        const data = await scoreRes.json();
        const newScores = data.scores || [];
        newScores.forEach(ns => {
          const exists = state.espnScores.findIndex(es => es.espnEventId === ns.espnEventId);
          if (exists !== -1) {
            state.espnScores[exists] = ns;
          } else {
            state.espnScores.push(ns);
          }
        });
      }
    } catch (e) {
      console.warn("Failed to fetch match-specific scoreboard:", e);
    }
  }

  render();
  initializeLivePlayer();
  loadCommentaryFeed();
  logAnalyticsWatch();
}

async function loadWatchChannelDetails() {
  const chan = state.channels.find(c => String(c.id) === state.watchChannelId);
  if (!chan) return;
  state.selectedChannelName = chan.name;
  state.selectedChannelUrl = chan.url;
  render();
  initializeChannelPlayer();
}

// 10. ESPN Scores Matching
function getMatchedEspnScore(match) {
  if (!match) return null;
  const homeName = match.home_team_id ? match.home_team?.name : match.home_team_custom_name;
  const awayName = match.away_team_id ? match.away_team?.name : match.away_team_custom_name;
  if (!homeName || !awayName) return null;

  return state.espnScores.find(es => {
    return (teamsMatch(homeName, es.homeTeam) && teamsMatch(awayName, es.awayTeam)) ||
           (teamsMatch(homeName, es.awayTeam) && teamsMatch(awayName, es.homeTeam));
  });
}

async function loadCommentaryFeed() {
  if (commentaryInterval) clearInterval(commentaryInterval);

  const score = getMatchedEspnScore(state.streamingMatch);
  if (!score || !score.espnEventId) {
    state.commentaryData = null;
    render();
    return;
  }

  state.loadingCommentary = true;
  render();

  const fetchCommentary = async () => {
    try {
      const res = await fetch(`${BACKEND_BASE}/api/live-commentary?event=${score.espnEventId}`);
      if (res.ok) {
        state.commentaryData = await res.json();
      }
    } catch (e) {
      console.warn('Commentary fetch error:', e);
    } finally {
      state.loadingCommentary = false;
      render();
    }
  };

  await fetchCommentary();
  commentaryInterval = setInterval(fetchCommentary, 7000);
}

function renderFallbackButtonsHTML() {
  return (state.streamingUrls || []).map((url, idx) => {
    const isSel = state.activeStreamIndex === idx;
    return `
      <button onclick="changeFallbackStream(${idx})" class="py-3 px-2 rounded-xl border text-xs font-black uppercase tracking-wider transition-all cursor-pointer truncate ${
        isSel ? 'bg-emerald-accent border-emerald-accent text-black font-extrabold shadow' : 'bg-slate-900 border-slate-850 text-slate-300 hover:bg-slate-800'
      }">
        ${state.streamingLabels[idx] || 'Server'}
      </button>
    `;
  }).join('');
}

window.changeFallbackStream = function(idx) {
  state.activeStreamIndex = idx;
  const containers = document.querySelectorAll('#fallback-servers-buttons-container');
  containers.forEach(container => {
    container.innerHTML = renderFallbackButtonsHTML();
  });
  initializeLivePlayer();
};

// 11. Custom Player Engine and Black Screen Detector
function initializeLivePlayer() {
  const container = document.getElementById('watch-player-viewport');
  if (!container) return;

  const activeUrl = state.streamingUrls[state.activeStreamIndex];
  if (!activeUrl) {
    container.innerHTML = `
      <div class="flex flex-col items-center justify-center p-8 bg-slate-955/60 border border-slate-900 rounded-3xl h-full text-center gap-2">
        <span class="text-3xl text-amber-500">⚠️</span>
        <h4 class="text-sm font-bold uppercase tracking-wider text-white">No stream source configured</h4>
        <p class="text-xs text-slate-500 max-w-xs">No active video link matches this fixture yet. Please return closer to kickoff.</p>
      </div>
    `;
    return;
  }

  renderVideoEngine(container, activeUrl, handlePlayerError, handlePlayerPlaying);
}

function initializeChannelPlayer() {
  const container = document.getElementById('channel-player-viewport');
  if (!container) return;

  if (!state.selectedChannelUrl) {
    container.innerHTML = `<div class="flex items-center justify-center h-full text-slate-500 text-xs font-bold uppercase">No channel url</div>`;
    return;
  }
  renderVideoEngine(container, state.selectedChannelUrl, (err) => console.error('Channel player error:', err), null);
}

