function setupPlayerEvents(containerEl, url, onError, onPlaying, accentColor, maxIcon, minIcon, isPotPlayer = false, isEngine4 = false) {
  const video = containerEl.querySelector('#custom-video');
  const playToggle = containerEl.querySelector('#play-toggle');
  const playIcon = containerEl.querySelector('#play-icon');
  const muteToggle = containerEl.querySelector('#mute-toggle');
  const muteIcon = containerEl.querySelector('#mute-icon');
  const volumeSlider = containerEl.querySelector('#volume-slider');
  const skipBack = containerEl.querySelector('#skip-back');
  const skipForward = containerEl.querySelector('#skip-forward');
  const timeDisplay = containerEl.querySelector('#time-display');
  const fsToggle = containerEl.querySelector('#fullscreen-toggle');
  const fsIcon = containerEl.querySelector('#fs-icon');
  const playerContainer = containerEl.querySelector('#player-container');

  // PotPlayer specific elements
  const potSeekBar = containerEl.querySelector('#pot-seek-bar');
  const potStatusOverlay = containerEl.querySelector('#pot-status-overlay');

  // Engine4 specific elements
  const logsToggleBtn = containerEl.querySelector('#logs-toggle-btn');
  const diagnosticsLogs = containerEl.querySelector('#diagnostics-logs');
  const clearLogsBtn = containerEl.querySelector('#clear-logs-btn');
  const logsContent = containerEl.querySelector('#logs-content');

  const triggerPotOverlay = (text) => {
    if (!potStatusOverlay) return;
    potStatusOverlay.textContent = text;
    potStatusOverlay.classList.remove('hidden');
    setTimeout(() => {
      potStatusOverlay.classList.add('hidden');
    }, 1200);
  };

  const addEngineLog = (msg) => {
    if (!logsContent) return;
    const timeStr = new Date().toLocaleTimeString();
    const newLog = document.createElement('div');
    newLog.className = 'border-l border-slate-900 pl-2 leading-relaxed';
    newLog.textContent = `[${timeStr}] ${msg}`;
    logsContent.prepend(newLog);
  };

  // Initialize HLS
  if (Hls.isSupported()) {
    const hls = new Hls({
      enableWorker: true,
      lowLatencyMode: true,
      maxBufferLength: 5,
      maxMaxBufferLength: 10,
      capLevelToPlayerSize: true,
      backBufferLength: 10
    });
    hls.loadSource(url);
    hls.attachMedia(video);
    hlsRef.current = hls;

    hls.on(Hls.Events.MANIFEST_PARSED, () => {
      video.play().catch(() => {});
      if (isEngine4) addEngineLog("Manifest parsed. Starting stream feed.");
    });

    hls.on(Hls.Events.ERROR, (event, data) => {
      if (data.fatal) {
        console.error('[HLS Fatal Error]', data);
        if (isEngine4) addEngineLog(`[Fatal Error] ${data.type} - ${data.details}`);
        onError(data.details);
      } else {
        if (isEngine4) addEngineLog(`[Warning] ${data.details}`);
      }
    });
  } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
    video.src = url;
    video.play().catch(() => {});
  }

  // Autoplay blocker recovery
  video.muted = true;
  video.play().then(() => {
    setTimeout(() => {
      video.muted = false;
      muteIcon.setAttribute('data-lucide', 'volume-2');
      if (window.lucide) window.lucide.createIcons();
    }, 500);
  }).catch(() => {});

  // Play/Pause events
  playToggle.addEventListener('click', (e) => {
    e.stopPropagation();
    if (video.paused) {
      video.play();
      playIcon.setAttribute('data-lucide', 'pause');
      if (isPotPlayer) triggerPotOverlay('[ PLAY ]');
    } else {
      video.pause();
      playIcon.setAttribute('data-lucide', 'play');
      if (isPotPlayer) triggerPotOverlay('[ PAUSE ]');
    }
    if (window.lucide) window.lucide.createIcons();
  });

  video.addEventListener('play', () => {
    playIcon.setAttribute('data-lucide', 'pause');
    if (window.lucide) window.lucide.createIcons();
    if (onPlaying) onPlaying();
  });

  video.addEventListener('pause', () => {
    playIcon.setAttribute('data-lucide', 'play');
    if (window.lucide) window.lucide.createIcons();
  });

  // Volume events
  muteToggle.addEventListener('click', (e) => {
    e.stopPropagation();
    video.muted = !video.muted;
    if (video.muted) {
      muteIcon.setAttribute('data-lucide', 'volume-x');
      volumeSlider.value = 0;
      if (isPotPlayer) triggerPotOverlay('[ Mute ]');
    } else {
      muteIcon.setAttribute('data-lucide', 'volume-2');
      volumeSlider.value = video.volume;
      if (isPotPlayer) triggerPotOverlay('[ Unmute ]');
    }
    if (window.lucide) window.lucide.createIcons();
  });

  volumeSlider.addEventListener('input', (e) => {
    video.volume = e.target.value;
    video.muted = e.target.value === '0';
    if (video.muted) {
      muteIcon.setAttribute('data-lucide', 'volume-x');
    } else {
      muteIcon.setAttribute('data-lucide', 'volume-2');
    }
    if (isPotPlayer) triggerPotOverlay(`[ Volume: ${Math.round(video.volume * 100)}% ]`);
    if (window.lucide) window.lucide.createIcons();
  });

  // skip events (PremiumPlayer only)
  if (skipBack && skipForward) {
    skipBack.addEventListener('click', (e) => {
      e.stopPropagation();
      video.currentTime = Math.max(0, video.currentTime - 10);
    });
    skipForward.addEventListener('click', (e) => {
      e.stopPropagation();
      video.currentTime = Math.min(video.duration || 0, video.currentTime + 10);
    });
  }

  // PotPlayer seek bar
  if (potSeekBar) {
    video.addEventListener('durationchange', () => {
      potSeekBar.max = video.duration || 100;
    });
    video.addEventListener('timeupdate', () => {
      potSeekBar.value = video.currentTime;
    });
    potSeekBar.addEventListener('input', (e) => {
      video.currentTime = e.target.value;
      triggerPotOverlay(`[ Seek: ${formatTime(video.currentTime)} ]`);
    });
  }

  // Engine4 logs toggle
  if (logsToggleBtn && diagnosticsLogs) {
    logsToggleBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      diagnosticsLogs.classList.toggle('hidden');
    });
    clearLogsBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      logsContent.innerHTML = '';
    });
    diagnosticsLogs.addEventListener('click', (e) => {
      e.stopPropagation();
      diagnosticsLogs.classList.add('hidden');
    });
  }

  // time display updates
  video.addEventListener('timeupdate', () => {
    const cur = formatTime(video.currentTime);
    const dur = video.duration && video.duration !== Infinity ? formatTime(video.duration) : 'LIVE';
    timeDisplay.textContent = `${cur} / ${dur}`;
  });

  function formatTime(secs) {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = Math.floor(secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }

  // Fullscreen
  fsToggle.addEventListener('click', (e) => {
    e.stopPropagation();
    if (!document.fullscreenElement) {
      playerContainer.requestFullscreen().then(() => {
        fsIcon.setAttribute('data-lucide', minIcon);
      });
    } else {
      document.exitFullscreen().then(() => {
        fsIcon.setAttribute('data-lucide', maxIcon);
      });
    }
    if (window.lucide) window.lucide.createIcons();
  });

  // Black screen detector
  startBlackScreenDetector(video, onError, onPlaying);
}

function renderStandardPlayerSkin(containerEl, url, onError, onPlaying) {
  containerEl.innerHTML = `
    <video 
      id="custom-hls-video" 
      class="w-full h-full bg-black rounded-2xl focus:outline-none border border-card-border"
      controls="controls"
      autoplay="autoplay"
      playsinline="playsinline"
      crossorigin="anonymous"
    ></video>
  `;
  const video = containerEl.querySelector('#custom-hls-video');
  if (Hls.isSupported()) {
    const hls = new Hls({ maxMaxBufferLength: 10, enableWorker: true });
    hls.loadSource(url);
    hls.attachMedia(video);
    hlsRef.current = hls;
    hls.on(Hls.Events.MANIFEST_PARSED, () => video.play().catch(() => {}));
    hls.on(Hls.Events.ERROR, (event, data) => {
      if (data.fatal) onError(data.details);
    });
  } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
    video.src = url;
    video.play().catch(() => {});
  }

  // Watch for black screen pixels
  startBlackScreenDetector(video, onError, onPlaying);
}

function startBlackScreenDetector(videoEl, onError, onPlaying) {
  const canvas = document.createElement('canvas');
  canvas.width = 16;
  canvas.height = 16;
  const ctx = canvas.getContext('2d');

  detectorInterval = setInterval(() => {
    if (!videoEl || videoEl.paused || videoEl.ended) return;
    try {
      ctx.drawImage(videoEl, 0, 0, 16, 16);
      const imgData = ctx.getImageData(0, 0, 16, 16).data;

      let isBlack = true;
      for (let i = 0; i < imgData.length; i += 4) {
        const r = imgData[i];
        const g = imgData[i+1];
        const b = imgData[i+2];
        if (r > 8 || g > 8 || b > 8) {
          isBlack = false;
          break;
        }
      }

      if (isBlack) {
        blackFrameCount++;
        if (blackFrameCount >= 4) {
          clearInterval(detectorInterval);
          onError('Black Screen Error');
        }
      } else {
        blackFrameCount = 0;
        if (onPlaying) onPlaying();
      }
    } catch (e) {
      // CORS security block, bypass checking to preserve active playback
    }
  }, 1000);
}

function handlePlayerError(msg) {
  console.warn('[Blogger Player Fallback] Error:', msg);

  if (!state.streamingUrls || state.streamingUrls.length <= 1) {
    state.playerError = msg;
    render();
    return;
  }

  const match = state.streamingMatch;
  const homeN = match.home_team_id ? match.home_team?.name : match.home_team_custom_name;
  const awayN = match.away_team_id ? match.away_team?.name : match.away_team_custom_name;

  // Identify label matches
  const matchedIdxs = [];
  state.streamingLabels.forEach((label, idx) => {
    if (matchChannelWithTeams(label, homeN, awayN)) {
      matchedIdxs.push(idx);
    }
  });

  let nextIndex = (state.activeStreamIndex + 1) % state.streamingUrls.length;
  if (matchedIdxs.length > 0) {
    const nextMatch = matchedIdxs.find(idx => idx > state.activeStreamIndex);
    if (nextMatch !== undefined) {
      nextIndex = nextMatch;
    } else {
      nextIndex = matchedIdxs[0];
    }
  }

  state.bufferState = 'Stalled';
  render();

  setTimeout(() => {
    state.activeStreamIndex = nextIndex;
    state.playerError = null;
    state.reconnecting = false;
    state.bufferState = 'Healthy';
    render();
    initializeLivePlayer();
  }, 150);
}

function handlePlayerPlaying() {
  state.playerError = null;
  state.reconnecting = false;
  state.bufferState = 'Healthy';
}

// Adsterra HTML Placement Parser
function getAdForPlacementHTML(placementKey) {
  if (!state.adsterra || !state.adsterra.is_enabled) return '';
  const config = state.adsterra.custom_scripts?.placements?.[placementKey];
  if (!config || !config.enabled) return '';

  // Return a placeholder div with a unique ID that we will evaluate after inserting the HTML
  const elementId = `ad-placement-${placementKey}-${Math.random().toString(36).substring(2, 9)}`;

  // Delay script execution until after render
  setTimeout(() => {
    const el = document.getElementById(elementId);
    if (!el) return;

    let htmlCode = '';
    if (config.type === 'banner') htmlCode = state.adsterra.banner_script;
    else if (config.type === 'banner_2') htmlCode = state.adsterra.custom_scripts?.banner_2_script;
    else if (config.type === 'native') htmlCode = state.adsterra.native_script;
    else if (config.type === 'social_bar') htmlCode = state.adsterra.social_bar_script;
    else if (config.type === 'popunder') htmlCode = state.adsterra.popunder_script;
    else if (config.type === 'interstitial') htmlCode = state.adsterra.custom_scripts?.interstitial_script;
    else if (config.type === 'display_link') {
      const url = state.adsterra.custom_scripts?.display_link;
      if (url) {
        el.innerHTML = `
          <div class="w-full flex justify-center py-2">
            <a href="${url}" target="_blank" rel="noopener noreferrer" class="w-full max-w-[468px] py-4 bg-slate-900/40 hover:bg-slate-900/60 border border-emerald-500/25 rounded-2xl flex flex-col items-center justify-center text-center gap-1 hover:border-emerald-500/50 transition-all duration-200">
              <span class="text-[10px] text-emerald-accent font-black uppercase tracking-wider">🔥 Sponsored Link</span>
              <span class="text-xs text-white font-bold">Click here to support our stream servers</span>
            </a>
          </div>
        `;
        return;
      }
    }

    executeAdPlacement(el, htmlCode);
  }, 50);

  return `<div id="${elementId}" class="ad-container my-4 w-full flex justify-center"></div>`;
}

function executeAdPlacement(elementEl, htmlCode) {
  if (!elementEl || !htmlCode) return;
  elementEl.innerHTML = '';

  const tempDiv = document.createElement('div');
  tempDiv.innerHTML = htmlCode;

  const scripts = tempDiv.getElementsByTagName('script');

  Array.from(tempDiv.childNodes).forEach((node) => {
    if (node.nodeName !== 'SCRIPT') {
      elementEl.appendChild(node.cloneNode(true));
    }
  });

  Array.from(scripts).forEach((script) => {
    const newScript = document.createElement('script');
    Array.from(script.attributes).forEach((attr) => {
      newScript.setAttribute(attr.name, attr.value);
    });
    if (script.innerHTML) {
      newScript.innerHTML = script.innerHTML;
    }
    elementEl.appendChild(newScript);
  });
}

// 12. Score sync updates countdowns
function getRemainingTime(timestamp) {
  const diff = new Date(timestamp).getTime() - Date.now();
  if (diff <= 0) return '00:00:00';
  const hours = String(Math.floor(diff / (1000 * 60 * 65))).padStart(2, '0');
  const mins = String(Math.floor((diff % (1000 * 60 * 65)) / (1000 * 60))).padStart(2, '0');
  const secs = String(Math.floor((diff % (1000 * 60)) / 1000)).padStart(2, '0');
  return `${hours}:${mins}:${secs}`;
}

// 13. DOM Renderer logic
function render() {
  const root = document.getElementById('app-root');
  if (!root) return;

  if (state.loading) {
    root.innerHTML = `
      <div class='flex flex-col items-center justify-center min-h-screen bg-[#090c10]'>
        <div class='animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-emerald-500'></div>
        <p class='text-sm text-slate-400 mt-4 font-semibold uppercase tracking-wider'>Portal matches is connecting...</p>
      </div>
    `;
    return;
  }

  // Determine the active page key
  let activePageKey = '';
  if (state.watchMatchId && state.streamingMatch) {
    activePageKey = `watch_match_${state.watchMatchId}`;
  } else if (state.watchChannelId) {
    activePageKey = `watch_channel_${state.watchChannelId}`;
  } else {
    activePageKey = `portal_index_${state.activeTab}`;
  }

  // If page has already rendered, run selective in-place updates to prevent player rebuild flicker
  if (state.lastRenderedPage === activePageKey) {
    // 1. Update announcements banner
    const annBannerEl = document.getElementById('announcement-banner-container');
    if (annBannerEl) {
      annBannerEl.innerHTML = renderAnnouncementBannerHTML();
    }

    // 2. Update news ticker settings
    const tickerContainerEl = document.getElementById('ticker-marquee-container');
    if (tickerContainerEl) {
      tickerContainerEl.innerHTML = renderTickerMarqueeHTML();
    }

    // 3. Update footer counters
    const footerContainerEl = document.getElementById('footer-counters-container');
    if (footerContainerEl) {
      footerContainerEl.innerHTML = renderFooterAndCountersHTML();
    }

    // 4. Update page-specific sub-components
    if (state.watchMatchId && state.streamingMatch) {
      const scoreEl = document.getElementById('mini-scorecard-container');
      if (scoreEl) {
        scoreEl.innerHTML = renderMiniScorecardHTML(state.streamingMatch);
      }
      const tabsEl = document.getElementById('match-center-tabs-container');
      if (tabsEl) {
        tabsEl.innerHTML = renderMatchCenterTabsHTML(state.streamingMatch);
      }
      const buttonsEl = document.getElementById('fallback-servers-buttons-container');
      if (buttonsEl) {
        buttonsEl.innerHTML = renderFallbackButtonsHTML();
      }
    } else if (state.watchChannelId) {
      // Watch channel page has no dynamic scorecard, but we could update channel selector list active state
    } else if (state.activeTab === 'streaming') {
      const buttonsEl = document.getElementById('fallback-servers-buttons-container');
      if (buttonsEl) {
        buttonsEl.innerHTML = renderFallbackButtonsHTML();
      }
      const { live, upcoming, finished } = getCategorizedMatches();
      const streamingFeatured = live.length > 0 ? live[0] : (upcoming.length > 0 ? upcoming[0] : (finished.length > 0 ? finished[0] : null));
      if (streamingFeatured) {
        const scoreEl = document.getElementById('mini-scorecard-container');
        if (scoreEl) {
          scoreEl.innerHTML = renderMiniScorecardHTML(streamingFeatured);
        }
        const tabsEl = document.getElementById('match-center-tabs-container');
        if (tabsEl) {
          tabsEl.innerHTML = renderMatchCenterTabsHTML(streamingFeatured);
        }
      }
    } else if (state.activeTab === 'channels') {
      const gridEl = document.getElementById('matches-grid-container');
      if (gridEl) {
        const filteredChannels = state.channels.filter(c => {
          if (!state.channelsQuery) return true;
          return c.name.toLowerCase().includes(state.channelsQuery.toLowerCase());
        });
        gridEl.innerHTML = filteredChannels.map(chan => {
          return `
            <div onclick="navigate({ channel: '${chan.id}' })" class="glass-panel p-4 rounded-2xl border border-card-border hover:border-slate-800 transition-all cursor-pointer flex flex-col items-center justify-center text-center gap-2 group">
              <div class="h-10 w-10 rounded-full bg-slate-900 flex items-center justify-center border border-card-border group-hover:bg-slate-800 transition-all overflow-hidden">
                ${chan.logo_url ? `<img src="${chan.logo_url}" alt="" class="h-full w-full object-cover" />` : `<i data-lucide="tv" class="h-5 w-5 text-emerald-accent"></i>`}
              </div>
              <span class="text-xs font-bold text-white uppercase tracking-wider truncate w-full">${chan.name}</span>
            </div>
          `;
        }).join('');
      }
    } else {
      // List tabs (live, upcoming, finished)
      const gridEl = document.getElementById('matches-grid-container');
      if (gridEl) {
        const { live, upcoming, finished } = getCategorizedMatches();
        const activeList = state.activeTab === 'live' ? live : (state.activeTab === 'upcoming' ? upcoming : finished);
        const ui = state.systemConfig?.custom_scripts?.app_ui_texts || {};
        const emptyTitle = ui.no_matches_title || 'No Matches Broadcasts';
        const emptyDesc = ui.no_matches_desc || 'There are no active matches in this tab. Tune in during kickoff schedules.';

        let listHtml = '';
        if (activeList.length === 0) {
          listHtml = `
            <div class="glass-panel p-16 text-center rounded-3xl border border-card-border">
              <i data-lucide="tv" class="h-12 w-12 text-slate-700 mx-auto mb-4"></i>
              <h3 class="text-base font-black text-white uppercase">${emptyTitle}</h3>
              <p class="text-xs text-slate-400 mt-1 max-w-sm mx-auto">${emptyDesc}</p>
            </div>
          `;
        } else {
          const matchCards = [];
          activeList.forEach((m, idx) => {
            matchCards.push(renderMatchCardHTML(m));
            if ((idx + 1) % 2 === 0) {
              const betweenAd = getAdForPlacementHTML('betweenMatches');
              if (betweenAd) {
                matchCards.push(`<div class="col-span-1 md:col-span-2">${betweenAd}</div>`);
              }
            }
          });
          listHtml = `
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
              ${matchCards.join('')}
            </div>
          `;
        }
        gridEl.innerHTML = listHtml;
      }
    }

    // Render notice modal if open
    const modalContainerId = 'modal-mount-root';
    let modalContainer = document.getElementById(modalContainerId);
    if (!modalContainer) {
      modalContainer = document.createElement('div');
      modalContainer.id = modalContainerId;
      document.body.appendChild(modalContainer);
    }
    modalContainer.innerHTML = renderNoticeModalHTML();

    if (window.lucide) window.lucide.createIcons();
    return; // SKIP FULL RENDER AND VIDEO RE-INITIALIZATION
  }

  // Otherwise, the page changed (e.g. clicked tabs or watch match transitioned)
  state.lastRenderedPage = activePageKey;

  // Render watch matches view vs navigation index
  if (state.watchMatchId && state.streamingMatch) {
    renderWatchMatchPage(root);
  } else if (state.watchChannelId) {
    renderWatchChannelPage(root);
  } else {
    renderPortalIndex(root);
  }

  // Render overlay modal
  const modalContainerId = 'modal-mount-root';
  let modalContainer = document.getElementById(modalContainerId);
  if (!modalContainer) {
    modalContainer = document.createElement('div');
    modalContainer.id = modalContainerId;
    document.body.appendChild(modalContainer);
  }
  modalContainer.innerHTML = renderNoticeModalHTML();

  // Re-init lucide icons dynamically
  if (window.lucide) window.lucide.createIcons();
  else if (window.Lucide) window.Lucide.createIcons();
}

function renderPortalIndex(root) {
  const ui = state.systemConfig?.custom_scripts?.app_ui_texts || {};
  const showStreamingTab = state.systemConfig?.custom_scripts?.enable_streaming_now !== false;

  const tabStreamingLabel = ui.tab_streaming_name || '📺 Streaming Now';
  const tabLiveLabel = ui.tab_live_name || '🔴 Live Now';
  const tabUpcomingLabel = ui.tab_upcoming_name || '📅 Upcoming';
  const tabFinishedLabel = ui.tab_finished_name || '🏁 Finished';
  const tabChannelsLabel = ui.tab_channels_name || '📺 Channels';

  const emptyTitle = ui.no_matches_title || 'No Matches Broadcasts';
  const emptyDesc = ui.no_matches_desc || 'There are no active matches in this tab. Tune in during kickoff schedules.';

  // Get match categories
  const { live, upcoming, finished } = getCategorizedMatches();
  const announcementsCount = state.announcements.filter(ann => !state.dismissedAnnouncements[ann.id]).length;

  // Determine active stream featured match
  const streamingFeatured = live.length > 0 ? live[0] : (upcoming.length > 0 ? upcoming[0] : (finished.length > 0 ? finished[0] : null));

  // Filter M3U channels
  const filteredChannels = state.channels.filter(c => {
    if (!state.channelsQuery) return true;
    return c.name.toLowerCase().includes(state.channelsQuery.toLowerCase());
  });

  let innerContent = '';

  if (state.activeTab === 'streaming') {
    if (!streamingFeatured) {
      innerContent = `
        <div class="glass-panel p-16 text-center rounded-3xl border border-card-border mt-6">
          <i data-lucide="tv" class="h-12 w-12 text-slate-700 mx-auto mb-4"></i>
          <h3 class="text-lg font-black text-white uppercase">No Streaming Now</h3>
          <p class="text-sm text-slate-400 mt-1">There are no matches scheduled for streaming at this moment.</p>
        </div>
      `;
    } else {
      // Render layout
      innerContent = `
        <div class="grid grid-cols-1 lg:grid-cols-3 gap-8 mt-6">
          <!-- Player viewport -->
          <div class="lg:col-span-2 space-y-6">
            <!-- watchAbovePlayer placement -->
            ${getAdForPlacementHTML('watchAbovePlayer')}

            <div id="watch-player-viewport" class="aspect-video w-full relative bg-slate-955 border border-card-border rounded-3xl overflow-hidden shadow-2xl">
              <!-- Embeds inside HlsPlayer -->
            </div>

            <!-- watchBelowPlayer placement -->
            ${getAdForPlacementHTML('watchBelowPlayer')}

            <!-- Fallback servers -->
            <div class="glass-panel p-6 rounded-2xl border border-card-border space-y-4">
              <div class="flex items-center justify-between">
                <div>
                  <h3 class="font-black uppercase text-xs text-slate-400 tracking-wider">Fallback Channels</h3>
                  <p class="text-[10px] text-slate-500 font-bold uppercase mt-0.5">Toggle feeds if experience lag</p>
                </div>
                <button onclick="initializeLivePlayer()" class="p-2 bg-slate-900 border border-slate-800 hover:bg-slate-800 rounded-xl transition-colors cursor-pointer">
                  <i data-lucide="refresh-cw" class="h-4 w-4 text-emerald-accent"></i>
                </button>
              </div>
              <div id="fallback-servers-buttons-container" class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                ${renderFallbackButtonsHTML()}
              </div>
            </div>
          </div>

          <!-- Sidebar -->
          <div class="space-y-6 flex flex-col h-[calc(100vh-280px)] min-h-[500px]">
            <!-- Mini Scorecard -->
            <div id="mini-scorecard-container">
              ${renderMiniScorecardHTML(streamingFeatured)}
            </div>

            <!-- Sidebar tabs content -->
            <div id="match-center-tabs-container" class="flex-1 flex flex-col overflow-hidden">
              ${renderMatchCenterTabsHTML(streamingFeatured)}
            </div>
          </div>
        </div>
      `;

      // Delayed init for HLS Player inside main thread
      setTimeout(() => {
        if (!state.streamingUrls || state.streamingUrls.length === 0) {
          loadWatchMatchDetails();
        } else {
          initializeLivePlayer();
        }
      }, 50);
    }
  } else if (state.activeTab === 'channels') {
    innerContent = `
      <div class="space-y-6 mt-6">
        <!-- Search channels -->
        <div class="relative">
          <input 
            type="text" 
            value="${state.channelsQuery}" 
            oninput="state.channelsQuery=this.value; render();" 
            placeholder="Search TV Channels..." 
            class="w-full px-5 py-3.5 pl-12 glass-input rounded-2xl text-sm"
          />
          <i data-lucide="search" class="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-500"></i>
        </div>

        <div id="matches-grid-container" class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
          ${filteredChannels.map(chan => {
            return `
              <div onclick="navigate({ channel: '${chan.id}' })" class="glass-panel p-4 rounded-2xl border border-card-border hover:border-slate-800 transition-all cursor-pointer flex flex-col items-center justify-center text-center gap-2 group">
                <div class="h-10 w-10 rounded-full bg-slate-900 flex items-center justify-center border border-card-border group-hover:bg-slate-800 transition-all overflow-hidden">
