  } else {
    // Matches index tabs (live, upcoming, finished)
    const activeList = state.activeTab === 'live' ? live : (state.activeTab === 'upcoming' ? upcoming : finished);
    const searchQuery = state.activeTab === 'upcoming' ? state.upcomingQuery : state.finishedQuery;

    let searchBarHtml = '';
    if (state.activeTab === 'upcoming' || state.activeTab === 'finished') {
      searchBarHtml = `
        <div class="relative mb-6">
          <input 
            type="text" 
            value="${searchQuery}" 
            oninput="if(state.activeTab==='upcoming'){state.upcomingQuery=this.value}else{state.finishedQuery=this.value}; render();" 
