        }
      });

      listHtml = `
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          ${matchCards.join('')}
        </div>
      `;
    }

    innerContent = `
      <div class="mt-6">
        ${searchBarHtml}
        <div id="matches-grid-container">
          ${listHtml}
        </div>
      </div>
    `;
  }

  root.innerHTML = `
