      <!-- Navigation header bar -->
      <header class="border-b border-card-border bg-[#090c10]/80 sticky top-0 z-40 backdrop-blur">
        <div class="max-w-6xl mx-auto px-4 py-4 flex flex-col md:flex-row items-center justify-between gap-4">
          <div class="flex items-center justify-between w-full md:w-auto">
            ${renderLogoHTML()}

            <!-- Bell notifications button (Mobile only) -->
            <div class="flex items-center gap-2 md:hidden">
