                  <span class="absolute -top-1 -right-1 h-3.5 w-3.5 rounded-full bg-red-600 border border-[#090c10] text-[8px] font-black text-white flex items-center justify-center">
                    ${announcementsCount}
                  </span>
                ` : ''}
              </button>
            </div>
          </div>

          <!-- Tab List -->
          <div class="flex items-center gap-3 overflow-x-auto md:overflow-visible w-full md:w-auto pb-1 md:pb-0 scrollbar-none justify-start md:justify-end">
            <nav class="flex items-center gap-1 bg-slate-955/40 p-1 border border-card-border rounded-2xl shrink-0">
              ${showStreamingTab ? `
                <button onclick="state.activeTab='streaming'; render();" class="px-3 py-1.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${
                  state.activeTab === 'streaming' ? 'bg-emerald-accent text-black font-extrabold shadow-sm' : 'text-slate-400 hover:text-white hover:bg-slate-900/60'
                }">${tabStreamingLabel}</button>
              ` : ''}
              <button onclick="state.activeTab='live'; render();" class="px-3 py-1.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${
                state.activeTab === 'live' ? 'bg-emerald-accent text-black font-extrabold shadow-sm' : 'text-slate-400 hover:text-white hover:bg-slate-900/60'
              }">${tabLiveLabel}</button>
              <button onclick="state.activeTab='upcoming'; render();" class="px-3 py-1.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${
                state.activeTab === 'upcoming' ? 'bg-emerald-accent text-black font-extrabold shadow-sm' : 'text-slate-400 hover:text-white hover:bg-slate-900/60'
              }">${tabUpcomingLabel}</button>
              <button onclick="state.activeTab='finished'; render();" class="px-3 py-1.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${
                state.activeTab === 'finished' ? 'bg-emerald-accent text-black font-extrabold shadow-sm' : 'text-slate-400 hover:text-white hover:bg-slate-900/60'
              }">${tabFinishedLabel}</button>
              <button onclick="state.activeTab='channels'; render();" class="px-3 py-1.5 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${
                state.activeTab === 'channels' ? 'bg-emerald-accent text-black font-extrabold shadow-sm' : 'text-slate-400 hover:text-white hover:bg-slate-900/60'
              }">${tabChannelsLabel}</button>
            </nav>

            <!-- Bell notifications button (Desktop) -->
            <button onclick="state.isNoticeModalOpen=true; render();" class="hidden md:flex relative p-2.5 bg-slate-900 hover:bg-slate-800 text-white border border-card-border rounded-xl transition-all items-center justify-center gap-1.5 cursor-pointer animate-in fade-in" title="View Announcements">
              <i data-lucide="bell" class="h-5 w-5 text-emerald-accent"></i>
              ${announcementsCount > 0 ? `
                <span class="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-red-600 border border-[#090c10] text-[9px] font-black text-white flex items-center justify-center">
                  ${announcementsCount}
                </span>
              ` : ''}
            </button>
          </div>
        </div>
      </header>

      <!-- headerTop Ad placement -->
      <div class="max-w-6xl mx-auto w-full px-4 mt-2">
        ${getAdForPlacementHTML('headerTop')}
      </div>

      <!-- Ticker Marquee Headline -->
      <div id="ticker-marquee-container">
        ${renderTickerMarqueeHTML()}
      </div>

      <!-- Hero Banner Section -->
      <div id="hero-banner-container" class="max-w-6xl mx-auto w-full px-4 mt-4 font-bangla">
        ${renderHeroBannerHTML()}
      </div>

      <!-- afterBanner Ad placement -->
      <div class="max-w-6xl mx-auto w-full px-4">
        ${getAdForPlacementHTML('afterBanner')}
      </div>

      <!-- Active Announcements slider list -->
      <div id="announcement-banner-container">
        ${renderAnnouncementBannerHTML()}
      </div>

      <main class="max-w-6xl w-full mx-auto px-4 mt-6">
        ${innerContent}
      </main>

      <!-- Footer counters -->
      <div id="footer-counters-container">
        ${renderFooterAndCountersHTML()}
      </div>
    </div>
  `;
}

function renderAnnouncementBannerHTML() {
  if (state.announcements.length === 0) return '';
  const valid = state.announcements.filter(a => !state.dismissedAnnouncements[a.id]);
  if (valid.length === 0) return '';

  const item = valid[0];
  return `
    <div class="max-w-6xl mx-auto w-full px-4 pt-6">
      <div class="bg-gradient-to-r from-emerald-500/10 to-amber-500/5 border border-emerald-500/20 p-4 rounded-2xl flex items-center justify-between gap-3 relative pr-12">
        <div class="flex items-center gap-3">
          <div class="h-10 w-10 shrink-0 bg-emerald-505/20 border border-emerald-500/30 rounded-xl flex items-center justify-center text-emerald-accent">
            <i data-lucide="bell" class="h-5 w-5"></i>
          </div>
          <div>
            <h4 class="text-sm font-black uppercase text-white tracking-wide font-bangla">${item.title}</h4>
            <p class="text-xs text-slate-300 font-medium mt-0.5 font-bangla">${item.message}</p>
          </div>
        </div>
        <button onclick="state.dismissedAnnouncements['${item.id}']=true; render();" class="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors cursor-pointer">
          <i data-lucide="x" class="h-4 w-4"></i>
        </button>
      </div>
    </div>
  `;
}

function navigateHome(event) {
  if (event) event.preventDefault();
  const showStreaming = state.systemConfig?.custom_scripts?.enable_streaming_now !== false;
  state.activeTab = showStreaming ? 'streaming' : 'live';
  state.watchMatchId = null;
  state.watchChannelId = null;
  state.selectedChannelUrl = null;
  state.streamingMatch = null;
  state.activeStreamIndex = 0;
  state.commentaryData = null;
  window.location.hash = '';
  render();
}

function renderLogoHTML() {
  const ticker = state.tickerSettings;
  const useLogoImage = ticker?.use_logo_image;
  const logoUrl = ticker?.logo_url;
  const siteName = ticker?.site_name || 'KHELE DAO LIVE';
  const ui = state.systemConfig?.custom_scripts?.app_ui_texts || {};
  const subtitleText = ui.header_subtitle || ticker?.header_subtitle || 'Premium Streaming Portal';

  if (useLogoImage && logoUrl) {
    return `
      <a href="#" onclick="navigateHome(event)" class="cursor-pointer select-none block">
        <img src="${logoUrl}" alt="${siteName}" class="h-10 md:h-14 w-auto max-w-[200px] md:max-w-[280px] object-contain hover:scale-[1.02] transition-transform duration-200" />
      </a>
    `;
  } else {
    const logoIconHtml = logoUrl 
      ? `<img src="${logoUrl}" alt="" class="h-8 w-8 object-contain rounded-lg border border-card-border" />`
      : `
        <div class="h-9 w-9 bg-emerald-500/10 rounded-xl border border-emerald-500/25 flex items-center justify-center">
          <i data-lucide="tv" class="h-5 w-5 text-emerald-accent"></i>
        </div>
      `;
    return `
      <a href="#" onclick="navigateHome(event)" class="flex items-center gap-3 cursor-pointer select-none">
        ${logoIconHtml}
        <div>
          <h1 class="text-sm font-black text-white uppercase tracking-widest leading-none">${siteName}</h1>
          <p class="text-[9px] text-emerald-accent font-bold uppercase tracking-widest mt-1 block">${subtitleText}</p>
        </div>
      </a>
    `;
  }
}

function renderHeroBannerHTML() {
  const ticker = state.tickerSettings;
  let bannerSrc = `${BACKEND_BASE}/banner.png`;
  if (ticker && ticker.banner_url) {
    bannerSrc = ticker.banner_url.startsWith('http') ? ticker.banner_url : `${BACKEND_BASE}${ticker.banner_url}`;
  }
  return `
    <section class="w-full rounded-2xl overflow-hidden border border-card-border shadow-2xl bg-[#090c10]">
      <img 
        src="${bannerSrc}" 
        alt="Live Sports Broadcasts" 
        class="w-full h-auto block" 
      />
    </section>
  `;
}

function renderTickerMarqueeHTML() {
  const ticker = state.tickerSettings;
  if (!ticker || !ticker.is_enabled) return '';

  const tickerBadge = state.systemConfig?.custom_scripts?.app_ui_texts?.ticker_badge || ticker.ticker_badge || '⚡ NEWS TICKER';

  return `
    <div class="bg-gradient-to-r from-red-955/80 via-[#0f1422] to-red-955/80 border-b border-card-border py-2 relative overflow-hidden flex items-center h-9 z-30">
      <div class="absolute left-0 top-0 bottom-0 px-3.5 bg-red-600 text-white font-black uppercase tracking-wider text-[9px] flex items-center justify-center z-10 shadow-md">
        ${tickerBadge}
      </div>

      <div class="w-full pl-28 pr-4">
        <marquee behavior="scroll" direction="left" scrollamount="5" onmouseover="this.stop();" onmouseout="this.start();" class="text-xs font-bold text-white tracking-wide font-bangla block">
          ${ticker.ticker_text}
        </marquee>
      </div>
    </div>
  `;
}

function renderFooterAndCountersHTML() {
  const ticker = state.tickerSettings;
  const showCounters = ticker?.show_counters;

  let countersHtml = '';
  if (showCounters) {
    const totalViewsFormatted = (state.totalViews || 0).toLocaleString();
    const liveCountFormatted = (state.liveCount || 0).toLocaleString();

    countersHtml = `
      <div class="max-w-6xl mx-auto w-full mt-8 mb-6 px-4">
        <div class="glass-panel p-6 rounded-3xl border border-card-border flex flex-col sm:flex-row justify-around items-center gap-6 text-center bg-gradient-to-r from-emerald-500/5 via-slate-900/40 to-emerald-500/5">
          <div class="space-y-1">
            <span class="text-slate-500 text-[10px] font-black uppercase tracking-widest block">Total Platform Views</span>
            <span id="total-views-counter-val" class="text-3xl font-black text-white tracking-tight">${totalViewsFormatted}</span>
          </div>

          <div class="h-px w-12 sm:h-12 sm:w-px bg-card-border"></div>

          <div class="space-y-1">
            <span class="text-slate-500 text-[10px] font-black uppercase tracking-widest block flex items-center justify-center gap-1.5">
              <span class="h-2.5 w-2.5 rounded-full bg-red-500 animate-pulse"></span>
              Active Concurrent Viewers
            </span>
            <span id="live-viewers-counter-val" class="text-3xl font-black text-emerald-accent tracking-tight">${liveCountFormatted}</span>
          </div>
        </div>
      </div>
    `;
  }

  return `
    <div class="max-w-6xl mx-auto w-full px-4">
      ${getAdForPlacementHTML('beforeFooter')}
    </div>
    ${countersHtml}
    <footer class="border-t border-card-border bg-[#07090d]/60 py-6 text-center text-xs font-bold text-slate-500 uppercase tracking-widest mt-auto">
      Developed by 
      <a href="https://tanvirtossar.netlify.app/" target="_blank" rel="noopener noreferrer" class="text-emerald-accent hover:text-emerald-400 underline decoration-dotted transition-colors">
        Tanvir Hossain
      </a>
    </footer>
  `;
}

function renderNoticeModalHTML() {
  if (!state.isNoticeModalOpen) return '';

  const visibleAnnouncements = state.announcements.filter(ann => !state.dismissedAnnouncements[ann.id]);

  return `
    <div class="fixed inset-0 bg-black/85 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div class="w-full max-w-lg glass-panel p-6 rounded-3xl space-y-6 relative border border-card-border shadow-2xl">
        <div class="flex justify-between items-center pb-3 border-b border-card-border">
          <div class="flex items-center gap-2">
            <i data-lucide="bell" class="h-5 w-5 text-emerald-accent"></i>
            <h3 class="text-sm font-black text-white uppercase tracking-wider">
              Important Broadcasts (${visibleAnnouncements.length})
            </h3>
          </div>
          <button onclick="state.isNoticeModalOpen=false; render();" class="p-1.5 text-slate-400 hover:text-white hover:bg-slate-900 border border-transparent hover:border-slate-800 rounded-xl transition-all cursor-pointer">
            <i data-lucide="x" class="h-5 w-5"></i>
          </button>
        </div>

        <div class="max-h-[300px] overflow-y-auto pr-1 space-y-4">
          ${visibleAnnouncements.length === 0 ? `
            <div class="text-center py-8 text-slate-500 text-xs font-semibold uppercase">
              No active broadcasts found.
            </div>
          ` : visibleAnnouncements.map((ann) => {
            const isHighPriority = ann.priority === 'high';
            return `
              <div class="p-4 rounded-2xl border transition-all relative pr-10 ${
                isHighPriority 
                  ? 'bg-red-500/5 border-red-500/20' 
                  : 'bg-slate-950/40 border-slate-900'
              }">
                <div class="flex justify-between items-start">
                  <h4 class="text-sm font-black text-white tracking-wide font-bangla">${ann.title}</h4>
                  ${isHighPriority ? `
                    <span class="px-2 py-0.5 bg-red-500/10 text-red-400 border border-red-500/20 rounded text-[8px] font-black uppercase tracking-wider shrink-0">
                      Urgent
                    </span>
                  ` : ''}
                </div>
                <p class="text-xs text-slate-300 font-medium mt-1.5 leading-relaxed font-bangla">
                  ${ann.message}
                </p>
                <button onclick="state.dismissedAnnouncements['${ann.id}']=true; render();" class="absolute right-3 top-3 p-1 text-slate-500 hover:text-slate-300 hover:bg-slate-900/60 rounded-lg transition-all cursor-pointer" title="Dismiss notice">
                  <i data-lucide="x" class="h-4.5 w-4.5"></i>
                </button>
              </div>
            `;
          }).join('')}
        </div>

        <div class="pt-4 border-t border-card-border flex justify-end">
          <button onclick="state.isNoticeModalOpen=false; render();" class="px-5 py-2.5 bg-slate-900 hover:bg-slate-800 text-slate-300 font-bold uppercase text-xs tracking-wider rounded-xl transition-all border border-card-border cursor-pointer">
            Dismiss
          </button>
        </div>
      </div>
    </div>
  `;
}

function renderMatchCardHTML(m) {
  const score = getMatchedEspnScore(m);
  const isLive = m.status === 'live' || (score && score.liveMinute);
  const isUpcoming = m.status === 'upcoming';

  const homeName = m.home_team_id ? m.home_team?.name : m.home_team_custom_name;
  const awayName = m.away_team_id ? m.away_team?.name : m.away_team_custom_name;
  const homeFlag = m.home_team_id ? m.home_team?.flag_url : m.home_team_custom_flag;
  const awayFlag = m.away_team_id ? m.away_team?.flag_url : m.away_team_custom_flag;

  const homeScore = score ? score.homeScore : (m.home_score ?? 0);
  const awayScore = score ? score.awayScore : (m.away_score ?? 0);
  const gameMin = score ? score.liveMinute : (m.live_minute || (m.status === 'live' ? 'LIVE' : ''));

  // Check if shootout tie breaker exists
  const hasShootout = score && score.homeShootoutScore !== undefined && score.homeShootoutScore !== null;
  const homeSScore = hasShootout ? score.homeShootoutScore : null;
  const awaySScore = hasShootout ? score.awayShootoutScore : null;

  // Scorers details
  const hScorers = score ? score.homeScorers : (m.home_scorers || '');
  const aScorers = score ? score.awayScorers : (m.away_scorers || '');

  let scoreContentHtml = '';
  if (isLive || m.status === 'finished') {
    scoreContentHtml = `
      <div class="flex flex-col items-center justify-center">
        <span class="text-2xl md:text-3xl font-black text-white tracking-tight whitespace-nowrap">${homeScore} - ${awayScore}</span>
        ${hasShootout ? `
          <span class="text-[10px] font-black text-emerald-accent uppercase mt-1">
            Pens: ${homeSScore} - ${awaySScore}
          </span>
        ` : ''}
      </div>
    `;
  } else if (isUpcoming) {
    scoreContentHtml = `
      <div class="match-countdown flex flex-col items-center" data-kickoff="${m.match_timestamp}">
        <span class="text-[9px] text-slate-500 font-bold uppercase tracking-wider block">KICKOFF</span>
        <span class="countdown-val font-mono text-[10px] text-emerald-accent font-bold mt-0.5">--:--:--</span>
      </div>
    `;
  } else {
    scoreContentHtml = `
      <span class="px-2.5 py-1 bg-slate-955 border border-slate-800 text-xs font-black rounded-lg text-slate-500 whitespace-nowrap">VS</span>
    `;
  }

  // Scorers container
  const scorersHtml = (hScorers || aScorers) ? `
    <div class="text-[10px] text-slate-400 bg-slate-950/40 p-2 rounded-xl border border-slate-900/50 flex justify-between gap-2 mt-1 w-full font-bangla">
      <div class="w-[45%] text-left text-slate-300 font-medium break-words">${hScorers}</div>
      <div class="w-[10%] text-center text-slate-500 font-bold">⚽</div>
      <div class="w-[45%] text-right text-slate-300 font-medium break-words">${aScorers}</div>
    </div>
  ` : '';

  // Stadium and Kickoff Info
  const stadiumHtml = `
    <div class="text-center space-y-1 w-full">
      <p class="text-slate-400 text-xs font-bold flex items-center justify-center gap-1">
        <i data-lucide="map-pin" class="h-3.5 w-3.5 text-emerald-accent"></i>
        ${m.stadium_name || 'International Stadium'}
      </p>
      <p class="text-slate-505/50 text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1">
        <i data-lucide="calendar" class="h-3 w-3"></i>
        ${m.match_date} • ${m.match_time.substring(0, 5)}
      </p>
    </div>
  `;

  // Bottom Buttons
  let buttonsHtml = '';
  if (isLive || isUpcoming) {
    buttonsHtml = `
      <div class="flex gap-4 border-t border-card-border pt-4 w-full">
        <button onclick="navigate({ watch: '${m.id}' })" class="flex-1 py-3 bg-emerald-accent hover:bg-emerald-500 text-black font-black uppercase text-xs tracking-wider rounded-xl transition-all flex items-center justify-center gap-2 cursor-pointer border-none outline-none">
          <i data-lucide="tv" class="h-4 w-4"></i>
          ${isLive ? 'Watch Live' : 'Watch Feed'}
        </button>
      </div>
    `;
  } else {
    buttonsHtml = `
      <div class="flex gap-4 border-t border-card-border pt-4 w-full">
        <button class="flex-1 py-3 border border-slate-850 bg-slate-900 text-slate-400 font-bold uppercase text-xs tracking-wider rounded-xl transition-all flex items-center justify-center gap-2 cursor-not-allowed outline-none">
          <i data-lucide="info" class="h-4 w-4"></i>
          Finished
        </button>
      </div>
    `;
  }

  return `
    <div class="glass-panel p-6 rounded-3xl border border-card-border flex flex-col justify-between gap-6 hover:border-slate-800 transition-all duration-200">

      <!-- Card Header (League and Status) -->
      <div class="flex justify-between items-start w-full">
        <span class="px-2.5 py-0.5 bg-slate-900 border border-slate-800 rounded-lg text-[9px] font-black uppercase tracking-wider text-slate-400">
          ${m.tournament_name || 'International'}
        </span>
        <span class="px-2.5 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider border ${
          isLive 
            ? 'bg-red-500/10 text-red-400 border-red-500/25 animate-pulse'
            : isUpcoming 
              ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/25'
              : 'bg-slate-800 text-slate-500 border-slate-700'
        }">
          ${isLive ? `LIVE ${gameMin ? `• ${gameMin}` : ''}` : m.status.toUpperCase()}
        </span>
      </div>

      <!-- Teams and Scores -->
      <div class="flex items-center justify-between text-center gap-1.5 w-full">
        <!-- Home -->
        <div class="w-[38%] shrink-0 flex flex-col items-center gap-2 min-w-0">
          <div class="h-14 w-20 bg-slate-900/60 rounded-2xl overflow-hidden border border-card-border flex items-center justify-center p-1 shadow">
            ${homeFlag ? `<img src="${homeFlag}" alt="${homeName}" class="h-full w-full object-cover rounded-lg" />` : `<span class="text-xs text-slate-500 font-black">HOME</span>`}
          </div>
          <span class="font-extrabold text-white text-sm truncate w-full font-bangla">${homeName}</span>
        </div>

        <!-- Score -->
        <div class="w-[24%] shrink-0 flex flex-col items-center justify-center">
          ${scoreContentHtml}
        </div>

        <!-- Away -->
        <div class="w-[38%] shrink-0 flex flex-col items-center gap-2 min-w-0">
          <div class="h-14 w-20 bg-slate-900/60 rounded-2xl overflow-hidden border border-card-border flex items-center justify-center p-1 shadow">
            ${awayFlag ? `<img src="${awayFlag}" alt="${awayName}" class="h-full w-full object-cover rounded-lg" />` : `<span class="text-xs text-slate-500 font-black">AWAY</span>`}
          </div>
          <span class="font-extrabold text-white text-sm truncate w-full font-bangla">${awayName}</span>
        </div>
      </div>

      <!-- Goal Scorers -->
      ${scorersHtml}

      <!-- Stadium -->
      ${stadiumHtml}

      <!-- Bottom buttons -->
      ${buttonsHtml}

    </div>
  `;
}

function renderMiniScorecardHTML(m) {
  const score = getMatchedEspnScore(m);
  const homeName = m.home_team_id ? m.home_team?.name : m.home_team_custom_name;
  const awayName = m.away_team_id ? m.away_team?.name : m.away_team_custom_name;
  const homeFlag = m.home_team_id ? m.home_team?.flag_url : m.home_team_custom_flag;
  const awayFlag = m.away_team_id ? m.away_team?.flag_url : m.away_team_custom_flag;

  const homeScore = score ? score.homeScore : (m.home_score ?? 0);
  const awayScore = score ? score.awayScore : (m.away_score ?? 0);
  const gameMin = score ? score.liveMinute : (m.live_minute || (m.status === 'live' ? 'LIVE' : 'UPCOMING'));

  // Check if shootout tie breaker exists
  const hasShootout = score && score.homeShootoutScore !== undefined && score.homeShootoutScore !== null;
  const homeSScore = hasShootout ? score.homeShootoutScore : null;
  const awaySScore = hasShootout ? score.awayShootoutScore : null;

  return `
    <div class="glass-panel p-5 rounded-2xl border border-card-border bg-gradient-to-b from-slate-900/40 to-slate-950/20">
      <div class="flex justify-between items-center text-center gap-1">
        <!-- Home -->
        <div class="w-[35%] flex flex-col items-center gap-1.5 min-w-0">
          <div class="h-10 w-14 bg-slate-955/80 rounded-lg overflow-hidden border border-card-border flex items-center justify-center p-0.5 shadow">
            ${homeFlag ? `<img src="${homeFlag}" alt="${homeName}" class="h-full w-full object-cover rounded" />` : `<span class="text-[9px] text-slate-500 font-bold">HOME</span>`}
          </div>
          <span class="font-bold text-white text-xs truncate w-full font-bangla">${homeName}</span>
        </div>

        <!-- Score -->
        <div class="w-[30%] flex flex-col items-center justify-center">
          <div class="flex items-center gap-1.5">
            <span class="text-2xl font-black text-white tracking-tight">${homeScore}</span>
            <span class="text-slate-600 font-bold text-xs">-</span>
            <span class="text-2xl font-black text-white tracking-tight">${awayScore}</span>
          </div>
          ${hasShootout ? `
            <span class="text-[10px] font-black text-emerald-accent uppercase mt-1">
              Pens: ${homeSScore} - ${awaySScore}
            </span>
          ` : ''}
          <span class="px-2 py-0.5 bg-red-500/10 text-red-400 border border-red-500/25 rounded-md text-[9px] font-black uppercase tracking-wider mt-1.5 animate-pulse">
            ${gameMin}
          </span>
        </div>

        <!-- Away -->
        <div class="w-[35%] flex flex-col items-center gap-1.5 min-w-0">
          <div class="h-10 w-14 bg-slate-955/80 rounded-lg overflow-hidden border border-card-border flex items-center justify-center p-0.5 shadow">
            ${awayFlag ? `<img src="${awayFlag}" alt="${awayName}" class="h-full w-full object-cover rounded" />` : `<span class="text-[9px] text-slate-500 font-bold">AWAY</span>`}
          </div>
          <span class="font-bold text-white text-xs truncate w-full font-bangla">${awayName}</span>
        </div>
      </div>
    </div>
  `;
}

function renderMatchCenterTabsHTML(m) {
  return `
    <div class="glass-panel rounded-2xl border border-card-border flex-1 flex flex-col overflow-hidden">
      <!-- Side Navigation tab buttons -->
      <div class="flex border-b border-card-border p-1 bg-slate-955/40">
        <button onclick="state.activeSideTab='commentary'; render();" class="flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex flex-col items-center justify-center gap-1 ${
          state.activeSideTab === 'commentary' ? 'bg-emerald-accent text-black font-extrabold shadow' : 'text-slate-400 hover:text-white'
        }">
          <span>Commentary</span>
        </button>
        <button onclick="state.activeSideTab='events'; render();" class="flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex flex-col items-center justify-center gap-1 ${
          state.activeSideTab === 'events' ? 'bg-emerald-accent text-black font-extrabold shadow' : 'text-slate-400 hover:text-white'
        }">
          <span>Events</span>
        </button>
        <button onclick="state.activeSideTab='telemetry'; render();" class="flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex flex-col items-center justify-center gap-1 ${
          state.activeSideTab === 'telemetry' ? 'bg-emerald-accent text-black font-extrabold shadow' : 'text-slate-400 hover:text-white'
        }">
          <span>Health</span>
        </button>
        <button onclick="state.activeSideTab='lineup'; render();" class="flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex flex-col items-center justify-center gap-1 ${
          state.activeSideTab === 'lineup' ? 'bg-emerald-accent text-black font-extrabold shadow' : 'text-slate-400 hover:text-white'
        }">
          <span>Lineup</span>
        </button>
      </div>

      <!-- Content Panel -->
      <div id="match-center-tab-content" class="flex-1 overflow-y-auto p-4 max-h-[350px]">
        ${renderMatchCenterPanelContent()}
      </div>
    </div>
  `;
}

function renderMatchCenterPanelContent() {
  if (state.loadingCommentary) {
    return `
      <div class="flex flex-col items-center justify-center py-12">
        <div class="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-emerald-500"></div>
        <span class="text-[9px] text-slate-500 uppercase font-black mt-2">Loading data...</span>
      </div>
    `;
  }

  const score = getMatchedEspnScore(state.streamingMatch);
  if (!score || !score.espnEventId) {
    return `
      <div class="text-center py-10 text-slate-500 font-bold uppercase text-[9px]">
        Live stats waiting to connect...
      </div>
    `;
  }

  const data = state.commentaryData || {};

  if (state.activeSideTab === 'commentary') {
    const comm = data.commentary || [];
    if (comm.length === 0) {
      return `<div class="text-center py-10 text-slate-500 font-bold uppercase text-[9px]">No commentary logged</div>`;
    }
    return `
      <div class="space-y-3.5">
        ${comm.map(c => {
          const isGoal = (c.type || '').toLowerCase().includes('goal');
          const isCard = (c.type || '').toLowerCase().includes('card');
          return `
            <div class="p-3 rounded-xl border flex gap-3 text-xs leading-relaxed ${
              isGoal ? 'bg-emerald-505/10 border-emerald-500/20 text-emerald-300' : (isCard ? 'bg-amber-500/10 border-amber-500/20 text-amber-300' : 'bg-slate-950/40 border-slate-900 text-slate-300')
            }">
              <span class="font-black text-emerald-accent shrink-0 min-w-[28px]">${c.clock || '0\''}</span>
              <div>
                <p class="font-medium">${c.text}</p>
                ${c.type ? `<span class="text-[9px] font-black uppercase tracking-wider opacity-60 block mt-1">${c.type}</span>` : ''}
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  if (state.activeSideTab === 'events') {
    const events = data.keyEvents || [];
    if (events.length === 0) {
      return `<div class="text-center py-10 text-slate-500 font-bold uppercase text-[9px]">No events registered</div>`;
    }
    return `
      <div class="space-y-3.5">
        ${events.map(e => {
          const isGoal = (e.type || '').toLowerCase().includes('goal');
          return `
            <div class="p-3 rounded-xl border flex gap-3 text-xs leading-relaxed ${
              isGoal ? 'bg-emerald-505/10 border-emerald-500/20 text-emerald-300 font-bold' : 'bg-slate-950/40 border-slate-900 text-slate-300'
            }">
              <span class="font-black text-emerald-accent shrink-0 min-w-[28px]">${e.clock || '0\''}</span>
              <div>
                <p class="font-semibold">${e.text}</p>
                <span class="text-[9px] font-black uppercase tracking-wider opacity-60 block mt-1">${e.type}</span>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  if (state.activeSideTab === 'telemetry') {
    return `
      <div class="space-y-3.5 text-xs font-bold">
        <div class="flex justify-between items-center py-1 border-b border-slate-900">
          <span class="text-slate-500">Live Status:</span>
          <span class="text-emerald-accent uppercase flex items-center gap-1">
            <span class="h-1.5 w-1.5 rounded-full bg-emerald-accent animate-ping"></span>
            ONLINE
          </span>
        </div>
        <div class="flex justify-between items-center py-1 border-b border-slate-900">
          <span class="text-slate-500">Active Channel:</span>
          <span class="text-white uppercase">${state.activeStreamIndex === 0 ? 'Primary' : 'Backup ' + state.activeStreamIndex}</span>
        </div>
        <div class="flex justify-between items-center py-1 border-b border-slate-900">
          <span class="text-slate-500">Network Latency:</span>
          <span class="text-white">1.8s (Low Delay)</span>
        </div>
        <div class="flex justify-between items-center py-1 border-b border-slate-900">
          <span class="text-slate-500">Buffer state:</span>
          <span class="${state.bufferState === 'Healthy' ? 'text-emerald-accent' : 'text-amber-500'}">${state.bufferState}</span>
        </div>
        <div class="flex justify-between items-center py-1">
          <span class="text-slate-500">ESPN Event ID:</span>
          <span class="text-white font-mono">${score.espnEventId}</span>
        </div>
      </div>
    `;
  }

  if (state.activeSideTab === 'lineup') {
    if (!data.rosters) {
      return `<div class="text-center py-10 text-slate-500 font-bold uppercase text-[9px]">No rosters posted yet</div>`;
    }

    const rosters = Object.values(data.rosters);
    const homeR = rosters.find(r => r.homeAway === 'home');
    const awayR = rosters.find(r => r.homeAway === 'away');

    const renderRosterHtml = (teamR, title) => {
      if (!teamR || !teamR.roster || teamR.roster.length === 0) return '';
      return `
        <div class="space-y-2 mt-4">
          <h4 class="text-xs font-black uppercase text-emerald-accent tracking-wider border-b border-slate-900 pb-1">${title} Lineup</h4>
          <div class="space-y-1.5">
            ${teamR.roster.map(p => {
              return `
                <div class="flex justify-between items-center text-xs text-slate-300 py-1 font-medium">
                  <div class="flex items-center gap-2">
                    ${p.jersey ? `<span class="font-bold text-[9px] text-slate-500 bg-slate-955 w-5 h-5 rounded-full flex items-center justify-center border border-card-border">${p.jersey}</span>` : ''}
                    <span>${p.athlete?.displayName || p.athlete?.name || 'Player'}</span>
                  </div>
                  <span class="text-[9px] uppercase text-slate-500 font-bold">${p.position?.abbreviation || p.position?.name}</span>
                </div>
              `;
            }).join('')}
          </div>
        </div>
      `;
    };

    const homeName = state.streamingMatch.home_team_id ? state.streamingMatch.home_team?.name : state.streamingMatch.home_team_custom_name;
    const awayName = state.streamingMatch.away_team_id ? state.streamingMatch.away_team?.name : state.streamingMatch.away_team_custom_name;

    return `
      <div class="space-y-4">
        ${renderRosterHtml(homeR, homeName)}
        ${renderRosterHtml(awayR, awayName)}
      </div>
    `;
  }
}

// 14. Watch details separate screen renderers
function renderWatchMatchPage(root) {
  const match = state.streamingMatch;
  const homeName = match.home_team_id ? match.home_team?.name : match.home_team_custom_name;
  const awayName = match.away_team_id ? match.away_team?.name : match.away_team_custom_name;

  root.innerHTML = `
    <div class="min-h-screen bg-[#090c10] text-[#f0f3f8] flex flex-col font-sans pb-12">
      <header class="border-b border-card-border bg-[#090c10]/80 sticky top-0 z-40 backdrop-blur">
        <div class="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
          <button onclick="navigate({ watch: null })" class="flex items-center gap-2 px-3 py-1.5 bg-slate-900 border border-slate-800 rounded-xl hover:bg-slate-800 transition-colors text-xs font-black uppercase tracking-wider text-slate-300 cursor-pointer">
            <i data-lucide="arrow-left" class="h-4 w-4 text-emerald-accent"></i>
            Back Home
          </button>
          <div class="text-right">
            <span class="text-[10px] text-emerald-accent font-black uppercase tracking-widest block">Watch Room</span>
            <span class="text-xs font-bold text-white uppercase">${homeName} vs ${awayName}</span>
          </div>
        </div>
      </header>

      <!-- headerTop Ad placement -->
      <div class="max-w-6xl mx-auto w-full px-4 mt-2">
        ${getAdForPlacementHTML('headerTop')}
      </div>

      <!-- Ticker Marquee Headline -->
      <div id="ticker-marquee-container">
        ${renderTickerMarqueeHTML()}
      </div>

      <!-- Hero Banner Section -->
      <div id="hero-banner-container" class="max-w-6xl mx-auto w-full px-4 mt-4 font-bangla">
        ${renderHeroBannerHTML()}
      </div>

      <!-- afterBanner Ad placement -->
      <div class="max-w-6xl mx-auto w-full px-4">
        ${getAdForPlacementHTML('afterBanner')}
      </div>

      <!-- Active Announcements slider list -->
      <div id="announcement-banner-container">
        ${renderAnnouncementBannerHTML()}
      </div>

      <main class="max-w-6xl w-full mx-auto px-4 mt-6">
        <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <!-- Player -->
          <div class="lg:col-span-2 space-y-6">

            <!-- watchAbovePlayer placement -->
            ${getAdForPlacementHTML('watchAbovePlayer')}

            ${match.status === 'upcoming' ? `
              <div class="aspect-video w-full relative bg-slate-955 border border-card-border rounded-3xl flex flex-col items-center justify-center p-6 text-center gap-4">
                <i data-lucide="calendar" class="h-16 w-16 text-emerald-accent animate-pulse"></i>
                <div>
                  <span class="text-[10px] text-emerald-accent font-black uppercase tracking-widest block">MATCH NOT STARTED</span>
                  <h3 class="text-xl font-black text-white mt-1 uppercase">${homeName} vs ${awayName}</h3>
                  <p class="text-xs text-slate-400 mt-1">Live broadcast will begin at match kickoff: ${match.match_date} • ${match.match_time.substring(0, 5)}</p>
                </div>
                <div class="match-countdown" data-kickoff="${match.match_timestamp}">
                  <span class="countdown-val font-mono text-base text-emerald-accent font-black">--:--:--</span>
                </div>
              </div>
            ` : `
              <div id="watch-player-viewport" class="aspect-video w-full relative bg-slate-955 border border-card-border rounded-3xl overflow-hidden shadow-2xl">
                <!-- Player wrapper Hlsjs -->
              </div>

              <!-- Fallback options -->
              <div class="glass-panel p-6 rounded-2xl border border-card-border space-y-4">
                <div class="flex items-center justify-between">
                  <div>
                    <h3 class="font-black uppercase text-xs text-slate-400 tracking-wider">Fallback Channels</h3>
                    <p class="text-[10px] text-slate-500 font-bold uppercase mt-0.5">Toggle feeds if experience lag</p>
                  </div>
                  <button onclick="initializeLivePlayer()" class="p-2 bg-slate-900 border border-slate-800 hover:bg-slate-800 rounded-xl transition-colors cursor-pointer">
                    <i data-lucide="refresh-cw" class="h-4 w-4 text-emerald-accent"></i>
                  </button>
                </div>
                <div id="fallback-servers-buttons-container" class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                  ${renderFallbackButtonsHTML()}
                </div>
              </div>
            `}

            <!-- watchBelowPlayer placement -->
            ${getAdForPlacementHTML('watchBelowPlayer')}

          </div>

          <!-- Sidebar -->
          <div class="space-y-6 flex flex-col h-[calc(100vh-140px)] min-h-[500px]">
            <div id="mini-scorecard-container">
              ${renderMiniScorecardHTML(match)}
            </div>
            <div id="match-center-tabs-container" class="flex-1 flex flex-col overflow-hidden">
              ${renderMatchCenterTabsHTML(match)}
            </div>
          </div>
        </div>
      </main>

      <!-- Footer counters -->
      <div id="footer-counters-container">
        ${renderFooterAndCountersHTML()}
      </div>
    </div>
  `;

  // Set player timeout execution in loop to map correct DOM ID
  setTimeout(() => {
    if (match.status !== 'upcoming') {
      if (!state.streamingUrls || state.streamingUrls.length === 0) {
        loadWatchMatchDetails();
      } else {
        initializeLivePlayer();
      }
    }
  }, 50);
}

