                  <div onclick="navigate({ channel: '${chan.id}' })" class="p-3 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${
                    isPlaying ? 'bg-emerald-505/10 border-emerald-accent text-white' : 'bg-slate-955/40 border-slate-900 text-slate-400 hover:border-slate-800 hover:text-white'
                  }">
                    <div class="flex items-center gap-2">
                      <i data-lucide="tv" class="h-4 w-4 text-emerald-accent"></i>
