      </div>
    </div>
  `;

  setTimeout(initializeChannelPlayer, 50);
}

// 15. Match countdown tick
function initMatchCountdowns() {
  // Single global interval to prevent leaks
  setInterval(() => {
    const countdowns = document.querySelectorAll('.match-countdown');
    countdowns.forEach(c => {
      const raw = c.getAttribute('data-kickoff');
      if (!raw) return;
      const valEl = c.querySelector('.countdown-val');
      if (valEl) {
        valEl.textContent = getRemainingTime(raw);
      }
    });
  }, 1000);
}

// 16. App Bootstrapper
document.addEventListener('DOMContentLoaded', initApp);

